<?php
namespace App\Modules\Counselor\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreCounselorRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('create',\App\Modules\Counselor\Models\Counselor::class)??false;}public function rules():array{return ['name'=>'required|string|max:255','slug'=>'required|string|max:255|alpha_dash|unique:counselors,slug','avatar'=>'nullable|image|max:4096','bio'=>'nullable|string','about'=>'nullable|string','degree'=>'nullable|string|max:255','license_number'=>'nullable|string|max:255','years_of_experience'=>'nullable|integer|min:0|max:100','languages'=>'nullable|array','languages.*'=>'string|max:100','instagram'=>'nullable|url|max:255','telegram'=>'nullable|url|max:255','whatsapp'=>'nullable|url|max:255','website'=>'nullable|url|max:255','linkedin'=>'nullable|url|max:255','meta_title'=>'nullable|string|max:255','meta_description'=>'nullable|string|max:500','is_active'=>'sometimes|boolean','is_public'=>'sometimes|boolean','specialty_ids'=>'sometimes|array','specialty_ids.*'=>'integer|distinct|exists:specialties,id'];}}
